        TomUserPreferenceDto.fromJson(e as Map<String, Object?>),
    ];
  }

  /// `PUT /preferences`
  ///
  /// Writes one preference of the caller, replacing any previous value. A value longer than 16384 bytes of JSON is refused (400, preferences.encoded.too_large); a write that would add a key beyond 256 preferences is refused (409, preferences.limit.exceeded).
  Future<TomUserPreferenceDto> writePreference({
    required TomUserPreferenceWriteRequest body,
  }) async {
    final response = await _send(
      'PUT',
      '/preferences',
      body: jsonEncode(body.toJson()),
      contentType: 'application/json',
